CREATE DATABASE Users
    DEFAULT CHARACTER SET = 'utf8mb4';

USE Users;

CREATE TABLE users (
    user_id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    gender ENUM('M','F','O') NULL,
    age INT NULL,
    height_cm INT NULL,
    weight_kg INT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- 임시 저장 데이터 일시 삭제함
ALTER TABLE Users
DROP COLUMN save_date;




-- user_level 테이블 생성

-- 나중에 추가

------------------------------------------------------------------



CREATE TABLE running_record (
    record_id VARCHAR(20) NOT NULL PRIMARY KEY,     -- 기록 식별자
    user_id INT UNSIGNED NOT NULL,                  -- FK: Users.user_id
    start_time DATETIME NOT NULL,                   -- 시작 시각
    end_time DATETIME DEFAULT NULL,                 -- 종료 시각
    distance_km DECIMAL(6,2) NOT NULL,              -- 총 거리(km)
    pace_km DECIMAL(6,1) DEFAULT NULL,              -- 평균 페이스
    route LONGTEXT DEFAULT NULL,                       -- 전체 경로 데이터(JSON 등)
    
    start_point VARCHAR(255),                       -- 시작 지점 주소
    end_point VARCHAR(255),                         -- 종료 지점 주소
    calories_kcal DECIMAL(10,2),                     -- 소모 칼로리
    
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, -- 생성 시각
    
    CONSTRAINT fk_user_id FOREIGN KEY (user_id)
        REFERENCES users(user_id)
        ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


---------------------------------------------------------

-- 심박수는 나중에 추가

----------------------------------------------------------------------------------------------

ALTER TABLE running_record
ADD COLUMN duration_time TIME


-- 운동시간 계산식
UPDATE running_record
SET duration_time = SEC_TO_TIME(TIMESTAMPDIFF(SECOND, start_time, end_time));



---------------------------------------------------------------------------------------------------

-- user에 먼저 값 추가






-- 사용자 데이터 삽입
-- ===========================
-- Runnerism: synthetic running_record INSERTS (rec001 ~ rec200)
-- Columns: record_ID, user_id, start_time, end_time, distance_km, pace_km, route, start_point, via1, via2, via3, end_point
-- end_time uses DATE_ADD(start_time_literal, INTERVAL <minutes> MINUTE)
-- ===========================



UPDATE running_record
SET duration_time =
    SEC_TO_TIME(
        TIMESTAMPDIFF(
            SECOND,
            STR_TO_DATE(start_time, '%Y-%m-%d %H:%i:%s'),
            STR_TO_DATE(end_time, '%Y-%m-%d %H:%i:%s')
        )
    )
WHERE end_time IS NOT NULL;




-- ===========================
-- running_record 테이블 수정
-- ===========================
ALTER TABLE running_record
MODIFY COLUMN route LONGTEXT DEFAULT NULL,
DROP COLUMN via1_point,
DROP COLUMN via2_point,
DROP COLUMN via3_point;